//! Emit `be/src/generated/wire.ts` from the types in this crate.
//!
//! Run with `cd shared && cargo run --bin gen-types`. The output is generated:
//! hand-editing it is a bug, exactly like hand-editing `output.css`.
//!
//! Every type is tagged `export_to = "wire.ts"`, so ts-rs collects them into
//! one module rather than a file each. This binary points it at `be`'s
//! generated directory and then prepends the header — a generated file that
//! does not say it is generated is one somebody edits.

use std::fs;
use std::path::PathBuf;
use ts_rs::Config;

const HEADER: &str = "\
// Generated by `cd shared && cargo run --bin gen-types`. Do not edit.
//
// The Rust definitions in shared/src/ are the source of truth. Changing a wire
// type means editing there, regenerating, and committing both in the same
// change — a hand-edit here is silently reverted by the next run, and the two
// ends drift the moment it is.

";

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let out_dir = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .parent()
        .expect("shared/ has a parent")
        .join("be")
        .join("src")
        .join("generated");

    // `be` resolves modules with "nodenext", which requires an explicit
    // extension on every relative import — and it imports .ts directly rather
    // than building, so ".ts" is the right one. Without this the generated file
    // fails be's own typecheck, which is a poor first impression for a file
    // nobody is allowed to edit.
    let cfg = Config::new()
        .with_out_dir(&out_dir)
        .with_import_extension(Some("ts"));
    shared::export_all(&cfg)?;

    // ts-rs wrote the declarations; the rest is ours.
    let path = out_dir.join("wire.ts");
    let generated = fs::read_to_string(&path)?;

    // Collapsing every type into one module makes ts-rs emit that module's
    // cross-references as imports from itself — `import type { JobInfo } from
    // "./wire.ts"` inside wire.ts — which TypeScript rejects as conflicting
    // with the local declaration. Dropped here rather than in the output,
    // because the output is not a file anybody may edit.
    let body: String = generated
        .lines()
        .filter(|l| !l.starts_with("import type") || !l.contains("from \"./wire.ts\""))
        .collect::<Vec<_>>()
        .join("\n");

    fs::write(&path, format!("{HEADER}{body}\n"))?;

    let bytes = fs::metadata(&path)?.len();
    println!("wrote {} ({bytes} bytes)", path.display());
    Ok(())
}
